PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, phone TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS email_codes(email TEXT PRIMARY KEY, digest TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(digest TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, resets_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plans(id TEXT PRIMARY KEY, name TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), duration_days INTEGER CHECK(duration_days>0), active INTEGER NOT NULL DEFAULT 1);
INSERT INTO plans(id,name,amount) VALUES('lifetime','Vĩnh viễn',200000) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS orders(order_code INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT UNIQUE NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), plan_id TEXT NOT NULL REFERENCES plans(id), amount INTEGER NOT NULL CHECK(amount>0), duration_days INTEGER, request_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','paid','cancelled','expired')), payment_link_id TEXT UNIQUE, checkout_url TEXT, qr_code TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), paid_at TEXT, UNIQUE(user_id,request_id));
INSERT INTO sqlite_sequence(name,seq) SELECT 'orders',999999999 WHERE NOT EXISTS(SELECT 1 FROM sqlite_sequence WHERE name='orders');
CREATE TABLE IF NOT EXISTS licenses(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), plan_id TEXT NOT NULL REFERENCES plans(id), order_id TEXT UNIQUE REFERENCES orders(id), key_hash TEXT UNIQUE NOT NULL, key_cipher TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','locked','revoked')), expires_at TEXT, installation_key TEXT, generation INTEGER NOT NULL DEFAULT 1, manual_request_id TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS activations(license_id TEXT NOT NULL REFERENCES licenses(id), component TEXT NOT NULL CHECK(component IN('addon','custom')), client_id TEXT NOT NULL, last_seen TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(license_id,component));
CREATE TABLE IF NOT EXISTS license_nonces(digest TEXT PRIMARY KEY, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(reference TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), payment_link_id TEXT NOT NULL, amount INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, target_id TEXT, created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS transaction_guard(value INTEGER NOT NULL CHECK(value=1));
CREATE INDEX IF NOT EXISTS orders_user_created ON orders(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS licenses_user_created ON licenses(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS nonces_expiry ON license_nonces(expires_at);
